    var d = { personId: val(form, 'personId') || me().id, type: type, from: val(form, 'from'), to: val(form, 'to') || val(form, 'from'), reason: type === 'special' ? val(form, 'reason') : '', note: val(form, 'note') };
    var single = d.from && d.from === d.to;
    d.halfStart = single ? !!val(form, 'half1') : !!val(form, 'halfStart');
    d.halfEnd = single ? false : !!val(form, 'halfEnd');
