          form.querySelector('[data-mailto]').setAttribute('href', E.mailtoUrl(to.email || '', cur.subject, cur.body));
          form.querySelectorAll('[data-mlang]').forEach(function (b) { b.setAttribute('aria-pressed', String(b.getAttribute('data-mlang') === lang)); });
