      h += '<section><h3>This week · ' + esc(dts(mon) + ' – ' + dts(sun)) + '</h3>' + (wk.length ? '<ul class="list">' + wk.map(function (x) { return li(x, true); }).join('') + '</ul>' : '<p class="sub">No leave this week.</p>') + '</section>';
