    var ss = E.sessionsOf(evs).sessions, W = 640, H = 64, x0 = 5 * 60, x1 = 22 * 60;
    var X = function (min) { return 8 + (W - 16) * Math.max(0, Math.min(1, (min - x0) / (x1 - x0))); };
