    var evs = (M.clock[pid] || []).filter(function (e) { return e.at.slice(0, 10) === date; });
    var rows = evs.map(function (e) { return { id: e.id, kind: e.kind, time: e.at.slice(11) }; });
    if (!rows.length) rows = [{ id: '', kind: 'in', time: '' }, { id: '', kind: 'out', time: '' }];
    else if (rows[rows.length - 1].kind !== 'out' && date < TODAY) rows.push({ id: '', kind: rows[rows.length - 1].kind === 'bs' ? 'be' : 'out', time: '' });
    var kinds = ['in', 'bs', 'be', 'out'], focusSet = false;
    function rowHtml(r, i) {
      return '<div class="evrow" data-row data-id="' + esc(r.id) + '"><label class="sr" for="ek' + i + '">Event ' + (i + 1) + '</label><select class="in sm" id="ek' + i + '" name="kind">' + kinds.map(function (k) { return opt(k, E.KIND_NAME[k], r.kind); }).join('') + '</select>' +
        '<label class="sr" for="et' + i + '">Time of event ' + (i + 1) + '</label><input class="in sm" type="time" id="et' + i + '" name="time" step="60" value="' + esc(r.time) + '"' + (!r.time && !focusSet ? (focusSet = true, ' data-autofocus') : '') + '>' +
        '<button type="button" class="btn icon sm ghost" data-rmrow aria-label="Remove event ' + (i + 1) + '">' + ic('trash') + '</button></div>';
    }
