        var list = Array.prototype.map.call(form.querySelectorAll('[data-row]'), function (el) {
          return { id: el.getAttribute('data-id'), kind: el.querySelector('select').value, at: date + 'T' + el.querySelector('input').value };
        }).filter(function (x) { return x.at.length > 11; });
