  var PAGES = { '': pageMe, calendar: pageCalendar, rota: pageRota, requests: pageRequests, people: pagePeople, time: pageTime, records: pageRecords, reports: pageReports, settings: pageSettings };

  // ── boot ─────────────────────────────────────────────────────────────────
  var fresh = false;
